<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<!-- <ul>			<a href="{pigcms{:U('Recruit/company_list')}" class="on">企业列表</a>		</ul> -->	</div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Recruit/resume_list')}" method="get">                    <input type="hidden" name="c" value="Recruit"/>                    <input type="hidden" name="a" value="resume_list"/>                    筛选: 					<if condition="$admin_area neq 3">						<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" style="display:inline"></div>					</if>                    <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="type">                        <option value="position_name" <if condition="$_GET['type'] eq 'position_name'">selected="selected"</if>>职位名称</option>                        <option value="name" <if condition="$_GET['type'] eq 'name'">selected="selected"</if>>姓名</option>                    </select>                    <input type="submit" value="查询" class="button"/>                    &nbsp;&nbsp;                    <input type="button" value="添加简历" class="button" onclick="window.o2oTop.artiframe('{pigcms{:U('resume_edit')}','添加简历','60%','60%',true,false,false,addbtn,'add',true);"/>                </form>            </td>        </tr>    </table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<thead>					<tr>						<th>编号</th>						<th>姓名</th>						<th>性别</th>						<th>手机号</th>						<th>学历</th>						<th>工作时间</th>						<th>期望职位</th>						<th>期望薪资</th>						<th>求职区域</th>						<th>更新时间</th>						<th>状态</th>						<th>是否隐藏</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list['list']">						<volist name="list.list" id="vo">							<tr>								<td>{pigcms{$vo.resume_id}</td>								<td>{pigcms{$vo.name}</td> 								<td><if condition="$vo['sex'] eq 1">男<elseif condition="$vo['sex'] eq 2"/>女<else/>未知</if></td>								<td>{pigcms{$vo.phone}</td>								<td>{pigcms{$vo.qualifications}</td>								<td>{pigcms{$vo.work_years}</td>								<td>{pigcms{$vo.position_name}</td>								<td>{pigcms{$vo.salary}</td>								<td>{pigcms{$vo.address}</td>                                <td>{pigcms{$vo.update_time|date='Y-m-d H:i:s',###}</td>								<td><if condition="$vo['has_work'] && $vo['has_education'] && $vo['self_introduction'] "><span style="color: green;">发布成功</span><else/><span style="color: red;">待完善信息</span></if></td>								<td><if condition="$vo['is_hide'] eq 0">否<else/>是</if></td>								<td>									<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('resume_edit',array('id'=>$vo['resume_id']))}','编辑','60%','60%',true,false,false,editbtn,'edit',true);">编辑</a>									|									<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('resume_detail',array('resume_id'=>$vo['resume_id']))}','详情',700,500,true,false,false,'','',true);">详情</a>									| <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.resume_id}" url="{pigcms{:U('resume_del')}">删除</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="15">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="16">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script><include file="Public:footer"/>